def first_unique_char(s: str) -> int:
    # Create a dictionary to store the count and last seen index of each character
    char_count = {}

    # Iterate over the string to populate the dictionary
    for i, char in enumerate(s):
        if char in char_count:
            char_count[char] = (-1, i)  # Mark as repeated by setting count to -1
        else:
            char_count[char] = (1, i)   # Set count to 1 and record the index

    # Find the first character with a count of 1
    for _, (count, index) in char_count.items():
        if count == 1:
            return index

    # If no unique character is found, return -1
    return -1

# Example usage:
print(first_unique_char("leetcode"))  # Output: 0
print(first_unique_char("loveleetcode"))  # Output: 2
print(first_unique_char("aabbcc"))  # Output: -1
```

